import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const ROOT = process.cwd();
const CHANGELOG_PATH = resolve(ROOT, "CHANGELOG.md");
const OUTPUT_PATH = resolve(ROOT, "src/config/changelog-raw.ts");

function generateModule(rawMarkdown: string): string {
  const normalized = rawMarkdown.replace(/\r\n/g, "\n");
  return [
    "// AUTO-GENERATED FROM /CHANGELOG.md BY scripts/sync-changelog.ts",
    "// Do not edit this file directly. Edit /CHANGELOG.md and run `npm run changelog:sync`.",
    "",
    `export const RAW_CHANGELOG_MD = ${JSON.stringify(normalized)};`,
    "",
  ].join("\n");
}

const raw = readFileSync(CHANGELOG_PATH, "utf8");
const checkOnly = process.argv.includes("--check");
const generated = generateModule(raw);

if (checkOnly) {
  let existing = "";
  try {
    existing = readFileSync(OUTPUT_PATH, "utf8");
  } catch {
    console.error("src/config/changelog-raw.ts is missing. Run `npm run changelog:sync`.");
    process.exit(1);
  }
  if (existing !== generated) {
    console.error("src/config/changelog-raw.ts is out of sync with CHANGELOG.md. Run `npm run changelog:sync`.");
    process.exit(1);
  }
  console.log("Changelog sync check passed: src/config/changelog-raw.ts matches CHANGELOG.md.");
  process.exit(0);
}

writeFileSync(OUTPUT_PATH, generated, "utf8");
console.log(`Synced CHANGELOG.md (${raw.length} bytes) -> src/config/changelog-raw.ts`);
